/* PRIVATE PREPARATION ONLY. These are possible evidence routes, not discoveries.
   Do not publish or seed player knowledge, conclusions, witnesses or past events. */
(() => {
  'use strict';
  const outline = 'Echo-Below-Campaign-Outline.md · approved foundation, Acts I–V and clue alternatives; supersedes older provisional explanations.';
  const continuity = 'Continuity-Reference.md · settled Echo/Nine backbone and custom floor overlays; read with the newer approved outline.';
  const aldric = 'Five-Character-Stories.md · Aldric corroboration ladder and consent limits; approved outline controls the restoration distinction.';
  const r = (id,title,source,method,access,independence,limit,characterIds) => ({id,title,source,method,access,independence,limit,characterIds});
  const topics = [
    {id:'echo',title:'The Echo',summary:'Compare a phenomenon across places; distinguish an older source from later users and theories.'},
    {id:'looking-glass',title:'Looking Glass',summary:'Establish what the apparatus does, what its makers intended, and where their predictions fail.'},
    {id:'family',title:'Ilyra and Tavin',summary:'Recover two people’s independent history without treating a reconstruction as proof of an original soul.'},
    {id:'ward-catastrophe',title:'The ward catastrophe',summary:'Reconstruct the interaction of civic protections and the evacuation, while leaving unestablished dates and locations open.'},
    {id:'aldric-return',title:'Aldric’s return',summary:'Investigate the return privately if Aldric wishes. His life and agency never depend on compliance, a ring or a machine.'},
    {id:'district',title:'The threatened district',summary:'Trace the present physical connections, identify who is affected, and develop tested choices with residents.'}
  ];
  const conclusions = [
    {
      id:'echo-observable',topic:'echo',title:'A repeatable relationship between places',question:'Do observations at Wave Echo and Undermountain support the same phenomenon?',
      dmTruth:'The custom Echo is resonance produced by the published knot in the Weave beneath Waterdeep. Wave Echo Cave is a responsive satellite, not a second knot. Similar sensations are a starting observation, not immediate knowledge of cause, all nine sites or a transport network.',stage:'early',
      observations:['Possible observation: a documented pressure response occurs after an ordinary physical event at each actually visited site. Preserve timing, conditions and failed repetitions.','A permitted baseline away from either location can show what the same method records under ordinary conditions.'],
      claims:['A researcher may call the two responses related; the author’s method and access still need checking.','An interested buyer may call every dark stone an Echo artifact; appearance alone supplies no measurement.'],
      inferences:['Matching behavior under comparable conditions supports a relationship more strongly than matching vocabulary.','A difference in strength can suggest a local source without proving its location or intelligence.'],
      openQuestions:['Which part of the response is repeatable?','What ordinary or unrelated magical causes remain plausible?','Who actually performed each observation, and with what equipment?'],
      corroborates:['Separate observers reproduce a bounded response using a stated method and an ordinary control.','Dated records preserve negative results as well as similarities.'],
      contradicts:['A copied description is presented as an independent measurement.','Only one instrument responds, including at the control location; its calibration needs review before claiming a shared cause.'],
      routes:[
        r('echo-field-pair','Two permitted field observations','Proposed observations made by the party at earned Forge and Undermountain locations.','Use the same mundane recording method and a control; compare the pressure component without inventing a second audible boom.','Requires actual access, safe conditions and any custodians’ consent; if the Forge was not investigated, that comparison remains available later.','The two observations are separate events; shared equipment remains a possible common error.','Similarity supports a relationship, not the Nine’s complete structure. Trista’s token or Echo’s Whisper is unnecessary.',['pc-pebble','pc-donavan']),
        r('echo-independent-log','Another expedition’s raw log','A proposed Gilded Compass or unrelated surveyor log from a genuinely completed outing.','Compare original notes, timing, route and calibration; interview its observer rather than accepting a copied conclusion.','Requires a plausible expedition, a willing owner and agreed copying terms; no log appears solely because a timer expired.','Independent only if the crew observed directly rather than repeating the party’s account.','A witness knows the surveyed stretch, not the hidden apparatus or every site.',['pc-ringgo','pc-trista']),
        r('echo-comparison-bench','A controlled comparison at Ninepin Works','Orren’s proposed bench record using legitimately obtained ordinary samples and field notes.','Blind-label permitted samples; ask a bounded question, include a control and let a second observer repeat the procedure.','Requires safe lawful samples, permission, agreed cost and an actual relevant method; a mundane clinometer does not become a magical detector.','New experimental work can challenge field interpretations; samples retain their collection chain.','A null result is useful. Orren does not identify a cosmic network from a single stone.',['pc-donavan','pc-aldric','pc-pebble'])
      ],links:['echo-predates-halaster','glass-amplifies'],choice:'Choose whether to repeat, publish a limited method, seek a different explanation or leave the question open.',source:outline+' '+continuity
    },
    {
      id:'echo-predates-halaster',topic:'echo',title:'An older phenomenon, a later investigator',question:'Did Halaster create the underlying resonance or find something already present?',
      dmTruth:'The knot and associated phenomenon predate Halaster’s research. He studied responsive sites and did not create Wave Echo Cave. The knot’s agency remains unconfirmed. This does not explain or excuse every later choice he made.',stage:'middle',
      observations:['A prepared older record can describe pressure, unusual dreams or digging behavior before a later research layer was added.','Physical strata or repairs may place a later experimental fixture after an earlier occupied structure.'],
      claims:['Halaster may claim credit for understanding something he did not create.','An opponent may describe the knot as a conscious director; that remains a theory requiring its own evidence.'],
      inferences:['Independent chronology can separate discovery from invention.','An old observation resembling a modern effect is stronger when linked by a repeatable comparison, not merely a shared poetic phrase.'],
      openQuestions:['How securely can these records be ordered without inventing an exact date?','What did their authors observe rather than believe?','Does any evidence support agency rather than a nonconscious magical process?'],
      corroborates:['Independent craft or civic chronology dates an observation before the apparatus or Halaster’s documented work.','A later lab record explicitly treats earlier measurements as findings it must explain.'],
      contradicts:['A purported ancient text uses a later copied diagram without disclosing the copy.','A theory equates Halaster’s later installation with creation of the underlying knot.'],
      routes:[
        r('echo-melairkyn','Earlier dwarven observations','Prepared custom overlay in an actually reached Lost Level context; published Melairkyn history stays intact.','Authenticate medium and provenance, translate bounded descriptions, and compare their sequence with later alterations.','Requires earned access or an authenticated surviving copy; no new room key, date or dwarven allegiance is implied.','An older local author is independent of Halaster only when provenance supports that separation.','Descriptions of dreams do not prove mind control, exact mechanism or universal effects.',['pc-pebble','pc-aldric']),
        r('echo-building-sequence','A sequence preserved in stone','Proposed permitted inspection of pre-existing masonry and later research fittings.','Record which fixture cuts or overlays which older surface; compare with an independent mason’s observations.','Use an accessible safe site and a qualified consenting reviewer; do not damage a protected ruin or infer access from a map icon.','Physical construction evidence differs from an author’s explanation, although interpretation still needs review.','Relative order establishes earlier/later, not the unknown origin of the knot or an exact century.',['pc-pebble','pc-trista']),
        r('echo-research-lineage','References to work the investigator inherited','Proposed apprenticeship correspondence or an external collection citing an older original.','Trace citations back toward originals and compare a independently kept source rather than counting copies.','Requires the current custodian’s permission and an actual collection prepared for the chosen lead.','A Halaster-associated letter is interested testimony; its externally preserved antecedent is the independent check.','Do not make an apprentice know every century or promote a book title into proof.',['pc-donavan','pc-ringgo'])
      ],links:['echo-observable','glass-amplifies','ward-overlap'],choice:'Separate what was found from what was built before deciding whom to question or hold responsible.',source:outline+' '+continuity
    },
    {
      id:'glass-amplifies',topic:'looking-glass',title:'Amplification is a means, not an answer',question:'What does Looking Glass change about the resonance?',
      dmTruth:'Looking Glass genuinely amplifies resonance. Its intended restoration application and its family’s soul identity are separate questions. Additional power allows larger effects without proving that the design is sound.',stage:'late',
      observations:['A prepared apparatus log can show input settings and increased measured response, with failures retained.','A bounded permitted test may reproduce a small amplification effect and reveal a limit or uncertainty.'],
      claims:['A proponent may call increased output proof of successful restoration.','A critic may call any study an automatic strengthening of the machine; this is not a campaign law.'],
      inferences:['Output changing with a controlled setting supports an amplification function.','A larger effect does not establish a returned person, safety or an obligation to complete the device.'],
      openQuestions:['What control was used and what else changed?','Which parts amplify, and which specify reconstructed content?','Where does power go when an intended effect fails?'],
      corroborates:['A reproducible limited effect matches an independently reviewed circuit or diagram.','A raw log retains contradictory results that an edited success summary omitted.'],
      contradicts:['The only evidence is Halaster’s confident label.','A claimed soul-restoration proof measures magnitude alone.'],
      routes:[
        r('glass-output-log','Raw output and failure records','Proposed Runestone-stage research record or authenticated equivalent recovered through an earned route.','Compare settings, measured outputs and failed runs; retain uncertainty rather than normalizing it away.','Requires actual access to the relevant work or a credible exported copy; the published local adventure remains primary.','The record originates with the experiment and is not independent of its maker; seek another method below.','It can establish recorded performance, not honesty of every annotation or an original soul’s presence.',['pc-donavan','pc-aldric']),
        r('glass-safe-output-test','A small independently witnessed test','A proposed isolated, bounded test designed after inspection by willing qualified practitioners.','State a prediction, control, limit and stop condition before trying a reversible low-output procedure.','Only proceed after the DM establishes feasible equipment, safety and consent; a test can be declined without blocking the mystery.','Fresh observations are independent of historical claims if reviewers can inspect the raw result.','No live district, unwilling participant or endangered character is a test load; scale-up remains unproved.',['pc-pebble','pc-donavan','pc-trista']),
        r('glass-fragment-review','A separated fragment with provenance','Prepared Looking Glass fragment on the Walking Tower, or an authenticated study obtained from its actual custodian.','Compare the component’s function and independently observed effect against the apparatus diagram.','Reach the tower by an earned physical route or negotiate a real report; the tower is not a free transport service.','Different physical component and observer can challenge the central lab’s account; a copied lab caption cannot.','The component supports one function; it does not reconstruct the entire device or reveal all controls.',['pc-pebble','pc-ringgo'])
      ],links:['glass-restoration','glass-contradictions','district-expansion'],choice:'Decide what further knowledge is worth obtaining, what can be published safely, and whether any limited use deserves a test.',source:outline+' '+continuity
    },
    {
      id:'glass-restoration',topic:'looking-glass',title:'A project to rebuild a lost environment',question:'Is Looking Glass an observational instrument, a restoration project, or both?',
      dmTruth:'Halaster wants his greatest unfinished undertaking to succeed and seeks to restore Ilyra and Tavin by reconstructing their environment. He abandoned work whose evidence contradicted him and now hopes further evidence will vindicate it. Understanding his grief does not establish consent or make the method safe.',stage:'middle',
      observations:['Prepared design iterations can add rooms, objects and people around the same restoration target.','A witnessed bounded reconstruction can reproduce a selected object or arrangement briefly, distinct from a mere drawn diagram.'],
      claims:['Halaster can present a remembered reunion as evidence that the project deserves continuation.','A surviving technician can describe one test and its stated purpose, not every hidden goal.'],
      inferences:['Recurring restoration specifications connect the technical project to a purpose more strongly than a name alone.','Different observers can agree that reconstructions occur while disagreeing about who or what they are.'],
      openQuestions:['Which specification describes an intended result and which describes one actually achieved?','What was omitted from the successful-run summary?','What does Halaster intend to change after a setback?'],
      corroborates:['A design brief, a separately kept participant account and a witnessed limited effect point to restoration.','Differences between an abandoned prediction and raw outcome explain revision without inventing another catastrophe.'],
      contradicts:['One evocative project name is treated as complete knowledge of purpose.','An edited result calls a temporary reconstruction permanent or independently consenting without evidence.'],
      routes:[
        r('glass-design-history','Abandoned and revised specifications','Proposed authenticated Looking Glass project sheets reached through existing research leads.','Compare revision marks, target descriptions and abandoned predictions; distinguish a plan from an outcome.','Requires a prepared accessible document chain; no published room is replaced or apprentice allegiance assumed.','Documents from one laboratory form one origin even when stored on different floors.','They show what the author attempted and recorded, not what every witness experienced.',['pc-donavan','pc-trista']),
        r('glass-technician-account','The survivor’s bounded account','The proposed restoration technician reached through Lantern House or independent expedition records.','Ask with consent about one known trial, compare their retained consent document and inspect a specific physical trace.','First establish the survivor’s identity, current life and requested help; no testimony is owed in exchange for rescue or care.','Personal testimony and a separately authenticated retained record can corroborate parts of a laboratory account.','Memory gaps do not invalidate moral judgment; the witness does not know Halaster’s whole family history.',['pc-aldric','pc-ringgo']),
        r('glass-material-event','An observed reconstruction with a comparison record','A prepared small anomaly or permitted test, with an ordinary before-record kept by another observer.','Document an object or room’s temporary change, preserve before/after sketches and ask a second observer to record separately.','Requires an event actually played or a consented bounded test; no automatic disaster or laboratory success is staged by opening this entry.','Independent before-record and firsthand observation avoid simply repeating the project description.','A changed room alone does not establish motive, family identity or that the same method caused every anomaly.',['pc-pebble','pc-trista','pc-donavan'])
      ],links:['glass-amplifies','glass-contradictions','family-ilyra-tavin','family-brief-reunion'],choice:'Choose whether to seek the people behind the design, challenge its methods, help the survivor, or investigate another explanation.',source:outline
    },
    {
      id:'glass-contradictions',topic:'looking-glass',title:'Contradiction destabilizes the reconstruction',question:'Why does Halaster keep enlarging the environment around the attempted return?',
      dmTruth:'Contradictions between a reconstruction and its surroundings destabilize it. Halaster responds by expanding the reconstructed area. A corrected detail in Tavin’s model reveals alteration, not proof that a reconstructed person lacks personhood.',stage:'middle',
      observations:['A prepared trial can have a measurable boundary failure near a specified mismatch.','A preserved model fragment or reliable independent drawing can differ from the device’s corrected reconstruction.'],
      claims:['Halaster may say a larger area will remove every contradiction.','A critic may claim one incorrect detail proves every reconstruction is empty imitation.'],
      inferences:['A repeated controlled mismatch may support a local instability mechanism.','Eliminating one mismatch may move the boundary problem instead of solving it.'],
      openQuestions:['Which mismatches matter, at what scale and under which settings?','Does a correction come from the apparatus, its instructions or a later repair?','What independent wishes does any sustained reconstruction express?'],
      corroborates:['A predeclared small comparison repeats a specific instability without a second simultaneous change.','Different historical records preserve the same deliberately crooked feature before the corrected version existed.'],
      contradicts:['An apparent stability improvement depends on hidden changes to power, duration or observers.','An investigator infers non-personhood from a geometry discrepancy alone.'],
      routes:[
        r('glass-mismatch-test','A bounded boundary comparison','Proposed safe limited test based on an inspected apparatus or a smaller independent model.','Compare a permitted harmless mismatch and control with clear observation limits and an immediate stop plan.','Requires expert review and a feasible bounded method; no resident’s home or sentient subject is volunteered by the party.','New experimental observations can test laboratory claims rather than merely restating them.','Local behavior cannot certify district-scale stability or predict every reconstruction.',['pc-donavan','pc-pebble']),
        r('glass-model-comparison','Tavin’s deliberately crooked street','A proposed authentic model fragment or reliable drawing, plus a separately sourced reconstruction record.','Establish the original’s custody; compare the deliberate crooked feature against the corrected version and record only the difference.','Acquire permission from both custodians; a name match alone does not authenticate an object.','The original family object/drawing must predate and be independent of the reconstruction record.','Altered detail does not prove a soul absent, memories false in full, or a person undeserving of care.',['pc-pebble','pc-trista']),
        r('glass-failure-chain','Different witnesses to expansion after failure','Proposed maintenance changes, a technician’s account and ordinary repair records from affected spaces.','Order one observed failure, one design expansion and its next result; check that each record describes the same trial.','Requires actual records or consenting witnesses reached through established leads.','Maintenance and affected-person records can be separate from the designer’s justification; shared copied dates remain one origin.','Correlation suggests a response pattern; it does not confirm every proposed cause or a promised final success.',['pc-ringgo','pc-aldric'])
      ],links:['glass-restoration','family-identity-open','district-expansion','district-interventions'],choice:'Test a smaller alternative, refuse an unsafe expansion, or ask what would make the design falsifiable before further work.',source:outline
    },
    {
      id:'family-ilyra-tavin',topic:'family',title:'Ilyra and Tavin had lives of their own',question:'Who were the people Halaster hopes to restore?',
      dmTruth:'Ilyra was Halaster’s spouse and a bookbinder. Tavin was their adopted twelve-year-old child, who made neighborhood maps and a deliberately crooked wooden model street with Halaster. Their identities should emerge through independent ordinary lives, not only his grief.',stage:'middle',
      observations:['A prepared commissioned repair can preserve Ilyra’s distinctive work and an externally kept attribution.','Tavin’s map can contain practical route marks and later family identification supported by another source.'],
      claims:['Halaster’s affectionate account is interested testimony with genuine emotional weight.','A descendant may preserve an unnamed child’s deed without knowing that child’s identity.'],
      inferences:['A craft record, correspondence and household evidence can identify the same people when details agree.','A shared occupation among modern residents does not make them replacements or descendants.'],
      openQuestions:['Which name, relationship and age are supported by which record?','What did each person choose and value outside Halaster’s account?','What remains private to living custodians?'],
      corroborates:['Independent customer records and correspondence agree on a maker’s identity.','A practical map and a separately kept family record support Tavin’s name and relationship.'],
      contradicts:['Halaster’s retelling is copied into three books and counted as three witnesses.','The court’s current residents are identified as family substitutes because of thematic similarities.'],
      routes:[
        r('family-binding','A repair and its independent commission','Prepared historical repaired book held by a willing custodian; Nessa can compare craft, not divine identity.','Compare physical binding with a separately maintained customer commission and permitted examples.','An earned archive or collector lead supplies access; obtain permission before copying a customer’s book.','The physical work and customer’s commercial record have different custodians and purposes if provenance supports it.','Technique alone identifies a tradition, not a unique maker; Nessa needs the attribution record.',['pc-trista','pc-donavan']),
        r('family-map-letter','A child’s practical map and a neighbor’s letter','Prepared Tavin map and independently preserved ordinary correspondence outside the dungeon.','Compare depicted routes and a mundane event mentioned by a neighbor; establish the child’s name and household separately.','Requires a plausible collection and custodian; original location/date remain unspecified until deliberately prepared.','The neighbor’s account must be direct or honestly labeled copied; map and letter cannot derive solely from Halaster.','A map does not certify every later family memory or any present soul identity.',['pc-pebble','pc-ringgo']),
        r('family-civic-household','A record of ordinary family life','Prepared adoption/household entry or civic equivalent, with a second external personal account.','Check names, relationship and record provenance; seek a separate account of work or play that the bureaucratic entry omits.','Choose period-appropriate records only after the original place and date are prepared; redact living people’s unrelated details.','A civic entry is independent of a family story when origin and later edits are known.','No exact historical address, date or neighboring lineage is invented by this template.',['pc-aldric','pc-donavan'])
      ],links:['family-brief-reunion','family-identity-open','ward-evacuation'],choice:'Decide how to preserve and share their history without reducing them to a research objective.',source:outline
    },
    {
      id:'family-brief-reunion',topic:'family',title:'A brief reunion gives hope, not proof',question:'What actually happened during the reconstruction Halaster remembers?',
      dmTruth:'A brief reconstruction of Ilyra recognized Halaster, recalled their private kettle joke, asked about Tavin and collapsed. The event gives his hope evidence without proving an original soul returned. Ilyra expressed no view about the present district experiment.',stage:'late',
      observations:['A prepared contemporaneous record can preserve a short exchange and its abrupt end.','An independent witness may have observed the duration or a question, without hearing every private word.'],
      claims:['Halaster calls this the return of his spouse.','A surviving record may describe the same event as an unstable reconstruction.'],
      inferences:['Recognition and a private memory are meaningful evidence of continuity, but several explanations remain possible.','An old request about Tavin is not consent to displace current residents.'],
      openQuestions:['Was the record edited, copied or interpreted after the event?','What could the apparatus or its maker already know about the remembered detail?','Can the identity question be answered with the evidence currently available?'],
      corroborates:['A separate witness or instrument record supports the event’s short duration and collapse.','An independently preserved family source establishes that the recalled kettle joke predates the experiment, if the custodian permits its use.'],
      contradicts:['A later summary adds a request to continue that no contemporaneous source contains.','A complete transcript is attributed to someone who only saw the room from outside.'],
      routes:[
        r('reunion-contemporaneous','The unedited trial record','Proposed original observation sheet or recording with a documented custody chain.','Compare its original sequence with later summaries; preserve recognition, kettle reference, Tavin question and collapse without adding dialogue.','Requires earned records access and authentication independent of Halaster’s present explanation.','Primary to the trial but still produced inside the experiment; it needs an outside check.','A recording establishes what was recorded, not the metaphysical identity of the speaker.',['pc-donavan','pc-trista']),
        r('reunion-witness','A witness to one part of the event','Prepared attendant or external observer reached by a credible surviving record; identity chosen during later prep.','Ask what they directly saw or heard, where they stood and when they wrote it down; compare only overlapping details.','The witness must plausibly survive or have left a genuinely independent contemporaneous account; no centuries-old eyewitness is invented casually.','An account kept outside Halaster’s editing can test a bounded part of the trial narrative.','The observer may verify a collapse without knowing the kettle joke, soul identity or current plan.',['pc-aldric','pc-ringgo']),
        r('reunion-private-detail','The remembered detail’s earlier source','A prepared private family note or authorized account preceding the trial, coupled with an independent run-timing record.','Determine whether the kettle detail existed before the experiment and who had access to it; compare independent timing with the trial account.','Ask the current custodian what can be used; intimate material can remain summarized or private.','Earlier family evidence and an external timing record can check different claims without duplicating the trial transcript.','A detail known to Halaster could have entered the reconstruction through him; authenticity of memory is not proof of soul return.',['pc-trista','pc-donavan'])
      ],links:['family-ilyra-tavin','family-identity-open','glass-restoration','district-expansion'],choice:'Acknowledge the evidence supporting Halaster’s hope while deciding which present actions it can justify.',source:outline
    },
    {
      id:'family-identity-open',topic:'family',title:'The original souls remain unconfirmed',question:'Does an apparently familiar reconstruction establish that Ilyra or Tavin’s original soul returned?',
      dmTruth:'The historical collapse severed victims’ magical identities from names, remains and possessions. Their souls cannot reliably be reached; ultimate fate remains unknown. A reconstruction’s personhood and an original soul’s return are distinct questions. No planned clue settles either by fiat.',stage:'late',
      observations:['Prepared records can describe failed attempts to reach identified victims, with the exact spell or method and constraints recorded.','A reconstruction may show recognitions or discrepancies; neither alone resolves the original soul’s fate.'],
      claims:['Halaster may treat recognition as identity.','An opponent may call failed contact proof that every soul was destroyed. Neither conclusion follows automatically.'],
      inferences:['Repeated bounded failures support an access problem, not universal proof of destruction.','The family-restoration problem differs materially from recovering a person whose remains and soul were identifiable.'],
      openQuestions:['What could each attempted method actually establish under its rules?','Was the target unwilling, unreachable, misidentified or otherwise outside the method’s limits?','What ethical duties apply to a reconstruction whose origin remains uncertain?'],
      corroborates:['Independent practitioners recorded method limits and compatible failures without consulting one another’s conclusions.','A known identifying anchor worked in a different case, establishing a contrast rather than a universal rule.'],
      contradicts:['One failed spell is presented as proof of soul destruction.','A changed model detail is treated as a license to dismiss a being’s expressed wishes.'],
      routes:[
        r('identity-contemporary-failures','Records of attempts after the disaster','Prepared contemporaneous practitioner case notes with identities redacted where appropriate.','Read the actual method, target information, result and declared limits; distinguish no response from confirmed destruction.','Requires permitted access to records whose provenance can be established; choose actual spell procedures only after rules review.','Separate practitioners are independent only if they performed separate attempts rather than copying one report.','The notes report limited failures; they do not reveal where the souls ultimately are.',['pc-donavan','pc-aldric']),
        r('identity-external-practitioner','An independent review of reachability','A proposed qualified practitioner outside Halaster’s project, consulting authenticated records and voluntarily provided evidence.','Ask for alternative explanations and the limits of available divination/resurrection methods; preserve a written uncertainty statement.','Agree cost, privacy and scope; no hazardous new resurrection attempt is required or automatically performed.','A fresh critique can expose overclaiming even without producing a new magical result.','Expert opinion does not become omniscient testimony or a guarantee that a soul is absent.',['pc-ringgo','pc-donavan']),
        r('identity-comparison-case','A documented case with different prerequisites','An authenticated anonymized successful return record; Aldric’s record only if he voluntarily authorizes that use.','Compare whether remains, identity and a recoverable soul were available, and how success was recognized.','Use a generic or redacted research route if Aldric declines. His ring, body, memories and confession are never required materials.','An independently witnessed case can challenge the claim that all restoration problems are identical.','A successful different case does not prove the family can be restored or disprove a reconstruction’s personhood.',['pc-aldric','pc-trista'])
      ],links:['family-brief-reunion','ward-overlap','aldric-restoration','aldric-independent'],choice:'Name what remains unknown and choose a consent-respecting response without pretending certainty.',source:outline+' '+aldric
    },
    {
      id:'ward-overlap',topic:'ward-catastrophe',title:'Civic protections collided during an emergency',question:'What caused the historical collapse that killed Halaster’s family?',
      dmTruth:'Generations of incompatible civic wards activated together during an emergency and caused the collapse. Halaster was away and did not cause it. The Crown’s later crimes against Aldric are separate. Original place, date and initiating emergency remain open for later preparation.',stage:'late',
      observations:['Prepared maintenance records can show multiple ward generations retained without a compatible activation plan.','An authenticated damage survey can record failures at their overlapping boundaries.'],
      claims:['A survivor may describe protective lights or conflicting orders without knowing the engineering cause.','An interested historian may blame a famous wizard; an attribution requires actual supporting evidence.'],
      inferences:['A sequence of activation, overlap and failure can support a civic engineering cause.','Absence from one account is not proof of guilt; causal evidence should be distinguished from blame.'],
      openQuestions:['What began the emergency?','Which activation and maintenance records are intact?','What original date and location should be prepared before specific records are authored?'],
      corroborates:['Independent maintenance designs and damage observations predict the same conflicting ward boundaries.','Separate emergency accounts establish an activation sequence without relying on Halaster’s explanation.'],
      contradicts:['A theory merges the disaster with Aldric’s Crown persecution because both harmed families.','A newly invented date or location is used to force the historical neighborhood onto modern Mending Court.'],
      routes:[
        r('ward-maintenance','Successive ward maintenance records','Proposed civic work orders and ward designs held by separate offices or later custodians.','Order installations and incompatible operating assumptions; identify where activation procedures overlapped.','Prepare the original civic context first; obtain access through earned archive or custodian leads.','Records made for maintenance differ in purpose from later blame narratives; copied diagrams retain their original author.','A drawing alone does not show which systems actually activated or what began the emergency.',['pc-donavan','pc-ringgo']),
        r('ward-damage-survey','A physical or contemporaneous damage survey','Prepared surviving ruin evidence, original survey or authenticated material record from the historical collapse.','Compare fracture/ward traces with predicted overlap zones using a qualified independent reviewer.','Requires a plausible accessible remnant or surviving primary survey; do not invent a reachable ruin in present Waterdeep.','Physical damage or a contemporaneous external survey can check the designers’ accounts.','Relative cause can be supported without fixing an unapproved calendar date, address or culprit.',['pc-pebble','pc-trista']),
        r('ward-emergency-accounts','Independent accounts of activation','Prepared emergency dispatch notes and separate survivor accounts, each limited to its author’s vantage point.','Build a cautious sequence of signals, activations and collapse; record disagreements and missing intervals.','Earn access to originals or honestly labeled copies; no single witness observed every ward.','Use at least two genuinely separate origins; multiple descendant copies of one account count once.','Accounts can establish sequence while leaving the triggering emergency and exact technical cause partly open.',['pc-aldric','pc-ringgo'])
      ],links:['ward-evacuation','family-identity-open','district-coupling'],choice:'Investigate the causal failure and preserve victims’ history without assigning an invented conspiracy.',source:outline
    },
    {
      id:'ward-evacuation',topic:'ward-catastrophe',title:'The family helped others escape',question:'What did Ilyra and Tavin do during the collapse?',
      dmTruth:'Ilyra helped maintain an evacuation passage; Tavin guided neighbors toward it. Both died when that passage collapsed. Halaster was away. Their last acts can be known through limited independent records without recreating their deaths or coercing a memory scene.',stage:'late',
      observations:['A prepared evacuation sketch can show a maintained passage and the route an unnamed young guide used.','Separate accounts may describe a bookbinder keeping access workable and a child leading others.'],
      claims:['Jori’s family preserves an account of an unnamed boy guiding an ancestor to safety.','A later memorial can name helpers but may derive from an earlier single account.'],
      inferences:['Independent identity records can connect separate descriptions to Ilyra and Tavin.','A family story supports a particular act; it does not make all courtyard residents descendants or chosen replacements.'],
      openQuestions:['Which identifying detail is independently supported?','Who actually reached safety, and which sources record a death versus a disappearance?','What parts of the account do current descendants wish to share?'],
      corroborates:['Tavin’s authenticated route map matches a survivor’s independently described path.','A separate work or household record identifies the bookbinder described by an evacuation witness.'],
      contradicts:['An unnamed child is identified as Tavin solely because that would be emotionally satisfying.','A later summary turns everyone in Mending Court into descendants without individual evidence.'],
      routes:[
        r('evacuation-descendant','The Fen family’s preserved account','Prepared account voluntarily shared by Jori or Pellan after ordinary familiarity.','Preserve its wording, named source and copying history; separate what the ancestor experienced from later family interpretation.','A genuine relationship and consent provide access; the family can decline or share only a limited passage.','The ancestor’s account is one origin, regardless of how many relatives retell it.','It describes an unnamed guide until an independent identifying source supports Tavin.',['pc-ringgo','pc-trista']),
        r('evacuation-map','A map made for people to use','Prepared authentic Tavin route map and separately maintained evacuation plan or survivor sketch.','Compare practical landmarks, exits and a distinctive route correction; authenticate authorship separately.','Requires actual permitted access and a prepared historical setting; no old map supplies a modern escape route automatically.','Independent map origins can corroborate movement rather than repeating a family name.','A route match supports a guide’s action, not every final moment or the present state of a soul.',['pc-pebble','pc-donavan']),
        r('evacuation-workers','Records of the maintained passage','Prepared porter, healer or emergency worker record with separate identity evidence for Ilyra.','Reconstruct one task and its timing; compare recorded survivors/deaths without embellishing a final speech.','Use an archive or custodian reached through play; no living witness must be invented to bridge centuries.','An operational account from outside the family checks a commemorative story.','Incomplete records may leave an individual’s precise final moment unknown even when the adopted overall history is supported.',['pc-aldric','pc-donavan'])
      ],links:['family-ilyra-tavin','ward-overlap','family-identity-open'],choice:'Decide how their acts are remembered and whether living people want their ancestors’ accounts published.',source:outline
    },
    {
      id:'aldric-restoration',topic:'aldric-return',title:'Aldric’s return had different prerequisites',question:'What evidence connects Halaster to Aldric’s return, and why is it a different case?',
      dmTruth:'Halaster’s experimental return restored Aldric using identifiable remains and a recoverable soul. His signet served as an identifying anchor, not a prison. Halaster did not cause the Crown’s crimes or arrange the deaths of Aldric’s family. Crown identity, family names and intermediary route remain open with Bowman.',stage:'middle',
      observations:['A prepared authenticated return record can contain identifying details Aldric chooses to compare privately.','A separate intermediary or attendant may corroborate one transfer or trial detail within their actual knowledge.'],
      claims:['Halaster may call Aldric proof that the family-restoration design will work.','Aldric’s fragmented memory can contain a true detail without establishing the whole causal chain.'],
      inferences:['Matching identifying evidence plus independent corroboration can support Halaster’s role.','A successful return with identifiable remains and a recoverable soul does not validate the unreachable-family case.'],
      openQuestions:['Which details does Aldric authorize researchers to examine or share?','Who transferred the remains, and what can that person actually know?','Which Crown and family details will Bowman establish through the character’s story?'],
      corroborates:['An authenticated laboratory record, separately sourced identification and bounded external witness account agree.','A neutral craft or office record matches the signet’s provenance without relying on Halaster’s claim.'],
      contradicts:['A boast or a triggered memory alone is labeled confirmed history.','A matching crest is used to infer Aldric’s guilt, family names or soul captivity.'],
      routes:[
        r('aldric-record','An authenticated return record','Prepared project record reached through earned research access.','Authenticate its author, alterations and custody; compare only identifying details Aldric elects to provide.','Aldric controls his participation and audience. An anonymized scientific comparison remains possible if he declines personal inquiry.','The record is laboratory-origin evidence and needs an independent identity or witness check.','It cannot establish Crown motives, every memory or the souls of his family.',['pc-aldric','pc-donavan']),
        r('aldric-intermediary','A witness to one part of the return','Prepared attendant/intermediary located through a credible ledger or independent contact.','Ask what they handled or witnessed, preserve timing and test one specific detail against another record.','Prepare a plausible identity and survival/account chain later; no witness is owed cooperation or knows the entire story.','A separately kept account or direct witness can corroborate a transfer independently of Halaster’s current narrative.','Do not imply the intermediary caused the Crown’s crimes or knew Aldric’s family without evidence.',['pc-aldric','pc-ringgo']),
        r('aldric-signature','Private identification without surrender','Edda Marr’s proposed provenance search using permitted signet sketches, craft commissions and office records.','Compare construction marks and institutional records to establish a bounded identity link; keep the original with Aldric.','Requires his consent, real archive access and agreed cost; do not remove the ring or invent Crown/family names.','Craft and civic records can be independent of laboratory claims when their provenance is established.','Identity evidence supports correlation to the return record; alone it does not identify the restorer.',['pc-aldric','pc-trista','pc-pebble'])
      ],links:['aldric-independent','family-identity-open','glass-restoration'],choice:'Aldric chooses whether to pursue, disclose, confront, or leave parts of the inquiry private; no progress requires a confession.',source:outline+' '+aldric
    },
    {
      id:'aldric-independent',topic:'aldric-return',title:'Aldric’s life is his own',question:'Does the return create an ongoing dependency or an obligation to Halaster?',
      dmTruth:'Aldric’s life and agency do not depend on the machine, the ring, Halaster’s continued consent or cooperation. He has no control switch. Independent survival encouraged Halaster’s hope but gives him no ownership over Aldric.',stage:'middle',
      observations:['A prepared maintenance chronology can identify an actual inactive interval while independently dated ordinary evidence places Aldric alive.','A qualified review can distinguish an identifying anchor used in a past procedure from a current sustaining connection.'],
      claims:['A coercive claimant may assert that continued help is owed for a past intervention.','Halaster may overstate what Aldric’s survival proves about another experiment.'],
      inferences:['A past causal role does not create present ownership or justify control.','Survival during a verified relevant interruption challenges a claimed sustaining dependency without requiring a dangerous new test.'],
      openQuestions:['What evidence best reassures Aldric without exposing private history?','Which apparatus interval or record genuinely applies to his procedure?','What choices does he want a second life to make possible?'],
      corroborates:['Independent records of his ordinary continued life overlap a verified inactive interval of the relevant apparatus.','Technical review finds an identification function rather than a documented ongoing sustaining requirement.'],
      contradicts:['Someone demands removing the ring, injuring Aldric or shutting down unknown live equipment to prove freedom.','A debt of obedience is inferred from a return he never agreed to purchase.'],
      routes:[
        r('aldric-ordinary-life','Ordinary evidence during a documented inactive interval','Prepared dated civic/medical/travel evidence chosen privately by Aldric, compared with authenticated apparatus maintenance records.','Check that the records overlap and concern the relevant equipment; corroborate activity with an independently sourced record.','Use existing benign records if plausible; if no supported inactive interval is available, pursue another route instead of inventing one.','Ordinary records originate outside the experiment, but their dates and identification still require consented authentication.','The comparison must concern a real interval; absence of a log is not proof a machine was off.',['pc-aldric','pc-ringgo']),
        r('aldric-procedure-review','Identification is not continued support','A qualified independent practitioner’s review of authenticated return design and permitted evidence.','Trace which components identified the subject during the completed procedure and whether the claimed continuing link appears in the actual design.','Aldric can allow redacted material; no ring removal, invasive examination or use of him as a test subject.','Fresh expert scrutiny can challenge a maker’s ownership claim; conclusions remain limited by inspected material.','An expert must not invent universal magical certainty or mechanisms absent from the record.',['pc-donavan','pc-aldric']),
        r('aldric-handoff','An account of completed discharge','Prepared separately retained release/handoff note or witness account from the end of the return procedure.','Compare the described completed transfer with what Aldric voluntarily confirms about later independent life.','Requires a credible surviving record/witness and his consent to personal comparison; public proof is unnecessary.','A separately held operational account differs from later promotional claims, provided it was not copied from them.','A witness can describe ending a procedure, not dictate what Aldric owes or settle every unexplained memory.',['pc-trista','pc-aldric'])
      ],links:['aldric-restoration','family-identity-open','district-interventions'],choice:'Let Aldric decide his response from agency and values, with care and privacy independent of what evidence he shares.',source:outline+' '+aldric
    },
    {
      id:'district-coupling',topic:'district',title:'The apparatus is connected to the modern district',question:'Why is the party’s present neighborhood within the proposed experiment?',
      dmTruth:'A physical apparatus connection couples a modern Waterdeep district to Looking Glass. That engineered connection makes it the proposed large-test site. It is not fate, a necessary ancestral location or proof that the original neighborhood stood here. Exact footprint and technical limits require later preparation.',stage:'late',
      observations:['Prepared city surveys can map repeated local disturbances against actual modern buildings.','An inspected apparatus connection can be traced toward a documented maintenance point.'],
      claims:['A supplier may describe an installation as harmless civic work without understanding its function.','Halaster may call the district a natural fit; the mechanism still needs independent checking.'],
      inferences:['A matched diagram, traced connection and independent local survey can identify threatened boundaries.','Present physical coupling does not establish the historical neighborhood’s location.'],
      openQuestions:['Which buildings and residents are actually within the measured footprint?','Which links are active, dormant or only planned?','What permissions, utilities or protections could an interruption also affect?'],
      corroborates:['A city survey and apparatus diagram agree on a connection independently supported by installation evidence.','A qualified inspection distinguishes an active physical link from an unrelated old ward.'],
      contradicts:['The courtyard is declared threatened solely because a family story feels relevant there.','Every Waterdeep anomaly is attributed to the same device without a matched connection.'],
      routes:[
        r('district-city-survey','Residents’ observations and an ordinary building survey','Prepared dated before-records and separately written observations from consenting residents, with a practical survey.','Map only actual observations, compare mundane renovations and inspect accessible shared spaces by permission.','Residents choose participation and private-space access; the app never stages a harmful anomaly to complete a checklist.','Separate contemporaneous observations can corroborate a location; people retelling one incident share that origin.','Clustering identifies where to investigate, not the complete apparatus or a proven catastrophe boundary.',['pc-pebble','pc-trista']),
        r('district-apparatus-trace','The physical connection from below','Prepared engineering diagram checked against a safely reached conduit, fitting or other actual apparatus link.','Trace identifiable segments and mark the unobserved gaps; compare with the independent city survey.','Requires earned dungeon access, current inhabitants’ responses and appropriate inspection; no teleport or automatic complete blueprint.','Physical inspection can correct a designer’s outdated plan; it is distinct from city testimony.','Do not claim unseen segments or a complete footprint until corroborated.',['pc-pebble','pc-donavan']),
        r('district-work-orders','Installation and maintenance outside the laboratory','Prepared supplier invoices, access agreements and a contractor’s limited account.','Follow a dated delivery to a witnessed installation point, checking serials or descriptions against actual hardware.','Ringgo or any character can negotiate legitimate record access; payment or favors require agreement.','Commercial records and an installer’s direct work may be independent of a lab diagram; duplicate invoices are one transaction.','An installer knows the task performed, not Halaster’s family, full intent or every technical consequence.',['pc-ringgo','pc-aldric'])
      ],links:['district-expansion','district-interventions','ward-overlap'],choice:'Decide what can be warned about now, what must still be surveyed, and whom to involve in the investigation.',source:outline
    },
    {
      id:'district-expansion',topic:'district',title:'A larger reconstruction endangers current lives',question:'What is Halaster preparing to impose, and what evidence supports a warning?',
      dmTruth:'Halaster plans to reconstruct his lost family’s wider environment upon the coupled present district, escalating scope when contradictions persist. Modern residents’ homes and lives are at risk. Preparation and a proposed test precede any reviewed deadline; refusal by the party does not activate it instantly.',stage:'late',
      observations:['Prepared revised specifications may enlarge a target boundary after a failed reconstruction.','Dated deliveries or control changes can support that preparations for a particular test are actually occurring.'],
      claims:['Halaster may promise that residents will be safe within a perfected reconstruction.','A fearful opponent may assert an immediate citywide catastrophe without a specific plan or measured reach.'],
      inferences:['Observed preparation plus a bounded mechanism can justify proportionate warning and protective action.','A schedule in one document is a proposed plan until corroborated by actual preparations and review.'],
      openQuestions:['What exact test is proposed, who is exposed, and what can stop or limit it?','Which hazards are observed, predicted or merely feared?','What alternate supplier or method would Halaster need if help is refused?'],
      corroborates:['Independent procurement or installation activity matches a current activation plan and surveyed footprint.','A limited trial shows a relevant displacement or instability mechanism without making a district-wide result inevitable.'],
      contradicts:['An old plan is treated as a live countdown despite changed components or missing preparations.','A threat expands to all Waterdeep without engineering evidence.'],
      routes:[
        r('expansion-current-plan','The current plan and its actual prerequisites','Prepared latest activation brief or authenticated working notes with a known revision chain.','Identify required components, intended area, proposed date and stop conditions; compare these against what is physically ready.','Access must be earned or legitimately supplied by a current participant; the DM establishes specific readiness before any deadline.','The plan is an interested primary source; its prerequisites can be checked independently.','A proposal is not a completed activation, and an uncorroborated date is not a running clock.',['pc-donavan','pc-trista']),
        r('expansion-procurement','Preparation visible beyond the laboratory','Prepared independent supplier, porter or installer accounts tied to actual deliveries.','Compare observed loads, destinations and timing with the plan; ask what remains undelivered rather than assuming completion.','Use real prepared actors and reachable records; declining a hook does not secretly complete every task.','Outside transactions can verify preparation without relying on Halaster’s narration.','Deliveries alone do not reveal soul identity, precise output or the intent of every worker.',['pc-ringgo','pc-pebble']),
        r('expansion-trial-cost','A bounded trial’s effects on surroundings','Prepared documented past trial or safely reviewed small comparison with independent observers.','Identify a specific effect on an existing object or boundary; compare before/after records and alternative causes.','Use a legitimate prior record or consented harmless test; do not harm residents to obtain persuasive evidence.','Affected-person observations and physical records can check the maker’s predicted benefits.','A local effect supports a risk model, not certainty that every resident will die or every intervention will fail.',['pc-aldric','pc-donavan','pc-trista'])
      ],links:['glass-contradictions','family-brief-reunion','district-coupling','district-interventions'],choice:'Warn and prepare with affected people, challenge the plan, interrupt a concrete prerequisite or seek a bounded alternative.',source:outline
    },
    {
      id:'district-interventions',topic:'district',title:'Several responses can become credible',question:'Which interventions are supported by tests, access and the choices of affected people?',
      dmTruth:'The campaign supports stopping/dismantling, persuading Halaster, a limited consensual rescue, responding during activation and preserving useful findings. None is guaranteed or locked behind all nine sites. Killing Halaster alone does not secure the apparatus; published rejuvenation matters. Destroying the knot is not a presumed available method.',stage:'finale',
      observations:['A prepared smaller test can establish one isolation or disconnection limit.','A practical survey can confirm an exit, warning route or reachable control with actual access restrictions.'],
      claims:['A site custodian may recommend a technique successful under local conditions.','A faction may advertise a single perfect solution; its assumptions need the same review as Halaster’s.'],
      inferences:['A transferable principle needs a local trial and independent review before district-scale use.','Several partial measures can protect people even when the main prevention plan fails.'],
      openQuestions:['What has each option actually demonstrated, and what failure remains possible?','Who consents, who bears the risk and who can stop the procedure?','What remains necessary after confronting or persuading Halaster?'],
      corroborates:['A technique’s local evidence, an independent small trial and a practical access plan agree within stated limits.','Residents and named helpers have actually agreed to specific preparations or roles.'],
      contradicts:['Collecting every site or surrendering a character is treated as mandatory for a solution.','A promising component is declared safe at full scale without testing, or consent is inferred from silence.'],
      routes:[
        r('intervention-site-principle','A site’s limited practical lesson','Prepared Frozen Door isolation, Walking Tower disconnection, Broken Star boundary evidence or another actually earned local lesson.','Work with affected custodians to learn one principle; preserve local conditions and perform a separate small comparison before proposing transfer.','Choose a useful available site or a consenting witness/record route; do not require visiting all eight satellites.','The site’s experience is independent of the central project, but copied traveler accounts need provenance.','A local success is not a complete district plan or a guaranteed magical power awarded to the party.',['pc-pebble','pc-donavan','pc-trista']),
        r('intervention-engineering','An independently reviewed interruption plan','Prepared inspection of actual apparatus controls and an outside qualified review.','List reachable interruption points, unstable remnants, required tools and stop/rollback conditions; rehearse only within safe limits.','Requires current physical access and permission where applicable; refusal or a missing control leads to another option.','Inspection plus an external reviewer can challenge both a designer’s promises and an opponent’s simplistic destruction plan.','No invented universal off-switch, permanent defeat through killing Halaster, or guaranteed destruction of the knot.',['pc-donavan','pc-aldric','pc-pebble']),
        r('intervention-resident-plan','A response people can actually carry out','Prepared resident-led warning, assistance and evacuation plans supported by Orenna, Anja and other willing actual contacts.','Walk feasible routes, agree signals and help requests, and test communication without a real emergency; connect that plan to the measured threat.','Each resident or helper chooses participation. The party cannot promise everyone’s consent or requisition private homes.','A practical rehearsal supplies independent evidence about readiness beyond any magical model.','Good evacuation protects options, not certainty of zero loss; it does not settle whether restoration should proceed.',['pc-ringgo','pc-trista','pc-aldric'])
      ],links:['district-coupling','district-expansion','glass-amplifies','glass-contradictions','aldric-independent'],choice:'Compare tested limits and affected people’s wishes, choose a primary response and a fallback, then record actual results instead of a predetermined ending.',source:outline+' '+continuity
    }
  ];
  globalThis.ECHO_MYSTERY_DATA = {
    version:1,status:'private-preparation',topics,conclusions,
    instructions:[
      'All observations, records, witnesses and routes here are preparation candidates. None is discovered, present, authenticated, believed or shared merely because this module loads.',
      'Stages describe pacing, not automatic unlocks. Actual evidence and player choices can arrive in a different order. A conclusion requires DM review of specific approved evidence and its audience.',
      'Separate firsthand observation, attributed claim, inference and open question. A proposed DM truth is not a player fact; unknown soul identity stays unknown.',
      'Three routes offer alternatives and checks, not three compulsory fetch quests. A core clue found through sound investigation should not disappear behind one failed roll; vary time, exposure or detail while preserving plausible other sources.',
      'Two copies, two descendants retelling one ancestor, or two witnesses repeating a single briefing are one source origin. Record provenance and conflicting evidence rather than counting documents.',
      'Keep the five characters optional participants. No essential conclusion requires Trista’s token, Aldric’s ring removal or confession, a specific spell, a sacrificed person, or every satellite visit.',
      'The historical catastrophe’s exact place, date and triggering emergency, the apparatus footprint, technical limits, and unassigned witness identities remain open until prepared. Never insert them into actual history automatically.',
      'The Crown’s crimes, Nezznar’s independent campaign and the old civic accident are separate causes. The knot’s agency remains unconfirmed. Modern district danger comes from engineered coupling.',
      'Use source books as read-only foundations for the actual dungeon and rules. Mystery explanations, family history and proposed research routes are custom Echo Below material under the approved outline.',
      'Publication uses existing review and audience controls. Personal evidence can remain owner-only or DM-only; no conclusion automatically completes an unrelated quest or appears on TV or phones.'
    ],
    source:outline+' '+continuity+' '+aldric
  };
})();
